import { InvalidStatusTransitionError, ValidationError } from '../errors/DomainErrors';
import { Money } from '../shared/Money';
import { Quantity } from '../shared/Quantity';
import { OrderLine } from './OrderLine';
import { OrderStatus, canTransition } from './OrderStatus';

export interface StatusChange {
  readonly status: OrderStatus;
  readonly at: Date;
}

export interface OrderSnapshot {
  readonly id: string;
  readonly customerId: string;
  readonly lines: ReadonlyArray<{ productId: string; quantity: number; unitPriceCents: number }>;
  readonly status: OrderStatus;
  readonly history: readonly StatusChange[];
}

export interface PlaceOrderProps {
  readonly id: string;
  readonly customerId: string;
  readonly lines: readonly OrderLine[];
  readonly placedAt: Date;
}

export class Order {
  private constructor(
    readonly id: string,
    readonly customerId: string,
    readonly lines: readonly OrderLine[],
    private currentStatus: OrderStatus,
    private readonly statusHistory: StatusChange[],
  ) {}

  static place(props: PlaceOrderProps): Order {
    if (props.customerId.trim() === '') {
      throw new ValidationError('An order requires a customer');
    }
    if (props.lines.length === 0) {
      throw new ValidationError('An order requires at least one line');
    }
    const productIds = new Set(props.lines.map((line) => line.productId));
    if (productIds.size !== props.lines.length) {
      throw new ValidationError('An order may contain each product only once');
    }
    return new Order(props.id, props.customerId, [...props.lines], 'placed', [
      { status: 'placed', at: props.placedAt },
    ]);
  }

  static restore(snapshot: OrderSnapshot): Order {
    const lines = snapshot.lines.map(
      (line) => new OrderLine(line.productId, Quantity.of(line.quantity), Money.ofCents(line.unitPriceCents)),
    );
    return new Order(snapshot.id, snapshot.customerId, lines, snapshot.status, [...snapshot.history]);
  }

  get status(): OrderStatus {
    return this.currentStatus;
  }

  get history(): readonly StatusChange[] {
    return [...this.statusHistory];
  }

  get total(): Money {
    return this.lines.reduce((sum, line) => sum.add(line.lineTotal), Money.zero());
  }

  pay(at: Date): void {
    this.transitionTo('paid', at);
  }

  pack(at: Date): void {
    this.transitionTo('packed', at);
  }

  ship(at: Date): void {
    this.transitionTo('shipped', at);
  }

  deliver(at: Date): void {
    this.transitionTo('delivered', at);
  }

  cancel(at: Date): void {
    this.transitionTo('cancelled', at);
  }

  toSnapshot(): OrderSnapshot {
    return {
      id: this.id,
      customerId: this.customerId,
      lines: this.lines.map((line) => ({
        productId: line.productId,
        quantity: line.quantity.value,
        unitPriceCents: line.unitPrice.cents,
      })),
      status: this.currentStatus,
      history: [...this.statusHistory],
    };
  }

  private transitionTo(target: OrderStatus, at: Date): void {
    if (!canTransition(this.currentStatus, target)) {
      throw new InvalidStatusTransitionError(this.currentStatus, target);
    }
    this.currentStatus = target;
    this.statusHistory.push({ status: target, at });
  }
}

