export const ORDER_STATUSES = ['placed', 'paid', 'packed', 'shipped', 'delivered', 'cancelled'] as const;

export type OrderStatus = (typeof ORDER_STATUSES)[number];

/** The only forward path an order may take. */
const FULFILMENT_SEQUENCE: readonly OrderStatus[] = ['placed', 'paid', 'packed', 'shipped', 'delivered'];

/** Cancellation is allowed only before the order has been shipped. */
const CANCELLABLE_STATUSES: ReadonlySet<OrderStatus> = new Set<OrderStatus>(['placed', 'paid', 'packed']);

export function isOrderStatus(value: string): value is OrderStatus {
  return (ORDER_STATUSES as readonly string[]).includes(value);
}

export function canTransition(from: OrderStatus, to: OrderStatus): boolean {
  if (to === 'cancelled') {
    return CANCELLABLE_STATUSES.has(from);
  }
  const index = FULFILMENT_SEQUENCE.indexOf(from);
  return index >= 0 && FULFILMENT_SEQUENCE[index + 1] === to;
}

